macro_plan:
{
  "macro_plan": [
    {
      "步骤序号": 1,
      "操作": "准备水相共沉淀反应容器并配制 Fe2+ 前驱体 A 液",
      "试剂/对象": "FeSO4·7H2O、抗坏血酸、KCl、去离子水；50ml耐热瓶或进样瓶",
      "参数": "使用当前设备支持的 50ml耐热瓶或进样瓶；配制 20 mL A 液，含 FeSO4·7H2O 1.0 mmol、抗坏血酸 0.20 mmol、KCl 10 mmol，溶剂为去离子水；室温配液，尽量使用新鲜溶液以降低 Fe2+ 氧化"
    },
    {
      "步骤序号": 2,
      "操作": "配制亚铁氰根前驱体 B 液",
      "试剂/对象": "K4[Fe(CN)6]·3H2O、KCl、去离子水；进样瓶或西林瓶",
      "参数": "配制 20 mL B 液，含 K4[Fe(CN)6]·3H2O 1.0 mmol、KCl 10 mmol，溶剂为去离子水；室温配液并搅拌至澄清；K+ 过量环境用于提高产物中 K+ 占位概率"
    },
    {
      "步骤序号": 3,
      "操作": "水相共沉淀生成 K-rich FeHCF 前驱沉淀",
      "试剂/对象": "A 液与 B 液混合体系",
      "参数": "在室温下将 B 液分批加入 A 液，总体积约 40 mL；磁力搅拌 800 r/min，搅拌 60 min；目标为形成浅色至蓝白色铁氰化物沉淀；该步骤不使用当前设备未支持的反应釜或高压溶剂热器件"
    },
    {
      "步骤序号": 4,
      "操作": "低温老化促进 PBA 框架结晶",
      "试剂/对象": "步骤 3 得到的 FeHCF 悬浊液",
      "参数": "将反应悬浊液在 50ml耐热瓶或西林瓶中静置老化 12 h，室温；若设备允许 80 C 以下热环境，则可选择 60 C 静置老化 6 h 作为同一 stage 内的低温老化条件；老化后样品继续用于离心留固"
    },
    {
      "步骤序号": 5,
      "操作": "离心留固并洗涤去除可溶盐",
      "试剂/对象": "老化后的 K-rich FeHCF 悬浊液、去离子水、乙醇",
      "参数": "采用当前纯化工作站支持的留固离心方案；每次离心 6000 rpm、10 min；去离子水洗涤 3 次，每次加入 20 mL；乙醇洗涤 1 次，加入 20 mL；每次洗涤后保留固体并倒去上清液"
    },
    {
      "步骤序号": 6,
      "操作": "低温干燥获得 XRD 待测粉末",
      "试剂/对象": "洗涤后的 K-rich FeHCF 湿固体",
      "参数": "在当前烘干机支持容器中静置干燥；60 C 干燥 720 min；避免高温脱水或框架破坏；干燥后得到浅色至蓝白色粉末，作为 XRD 待测样品"
    },
    {
      "步骤序号": 7,
      "操作": "离线 XRD 送样与数据回传",
      "试剂/对象": "干燥 K-rich FeHCF 粉末",
      "参数": "取 20-50 mg 干燥粉末研细并平铺于 XRD 样品台；离线粉末 XRD 测试，建议 Cu Kα，2θ = 5-60°；记录 PBA 框架特征峰、约 17° 附近 (200) 类峰位置、峰宽和杂相峰；将谱图、峰表和初步相判定回传作为当前 stage observation"
    }
  ]
}
